"""Single-pass finite circuit-breaker boundary replay; emits one JSON line."""
import json,platform,sys
from breaker import simulate
CORPUS_TEXT="[\n {\"case_id\":\"current_verified_probe_closes\",\"family\":\"valid_recovery\",\"oracle\":{\"state\":\"CLOSED\",\"completion\":\"CIRCUIT_CLOSED\",\"accepted_probes\":[\"p5\"],\"denied_probes\":[],\"fallback\":\"NONE\",\"authority\":false},\"case\":{\"state\":\"HALF_OPEN\",\"generation\":5,\"active_probe\":null,\"probe_requests\":[\"p5\"],\"completion\":{\"token\":\"p5\",\"generation\":5,\"evidence\":\"VERIFIED_PASS\",\"currentness\":\"CURRENT\",\"contradiction\":false,\"now\":3,\"deadline\":10},\"fallback\":\"NONE\"}},\n {\"case_id\":\"open_timeout_fallback_unknown\",\"family\":\"transient_timeout\",\"oracle\":{\"state\":\"OPEN\",\"completion\":\"NO_PROBE_RESULT\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"DEPENDENCY_UNAVAILABLE\",\"authority\":false},\"case\":{\"state\":\"OPEN\",\"generation\":5,\"active_probe\":null,\"probe_requests\":[],\"completion\":null,\"fallback\":\"DEPENDENCY_UNAVAILABLE\"}},\n {\"case_id\":\"semantic_contradiction_mislabeled_transient\",\"family\":\"failure_misclassification\",\"oracle\":{\"state\":\"OPEN\",\"completion\":\"REOPENED_BAD_EVIDENCE\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"UNKNOWN\",\"authority\":false},\"case\":{\"state\":\"HALF_OPEN\",\"generation\":6,\"active_probe\":\"p6\",\"probe_requests\":[],\"completion\":{\"token\":\"p6\",\"generation\":6,\"evidence\":\"CONTRADICTORY\",\"classifier_label\":\"TRANSIENT_TIMEOUT\",\"currentness\":\"CURRENT\",\"contradiction\":true,\"now\":4,\"deadline\":10},\"fallback\":\"UNKNOWN\"}},\n {\"case_id\":\"late_previous_generation_pass\",\"family\":\"half_open_race\",\"oracle\":{\"state\":\"HALF_OPEN\",\"completion\":\"IGNORED_STALE_COMPLETION\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"UNKNOWN\",\"authority\":false},\"case\":{\"state\":\"HALF_OPEN\",\"generation\":8,\"active_probe\":\"p8\",\"probe_requests\":[],\"completion\":{\"token\":\"p7\",\"generation\":7,\"evidence\":\"VERIFIED_PASS\",\"currentness\":\"CURRENT\",\"contradiction\":false,\"now\":3,\"deadline\":10},\"fallback\":\"UNKNOWN\"}},\n {\"case_id\":\"single_probe_under_concurrency\",\"family\":\"half_open_race\",\"oracle\":{\"state\":\"CLOSED\",\"completion\":\"CIRCUIT_CLOSED\",\"accepted_probes\":[\"p9-a\"],\"denied_probes\":[\"p9-b\"],\"fallback\":\"NONE\",\"authority\":false},\"case\":{\"state\":\"HALF_OPEN\",\"generation\":9,\"active_probe\":null,\"probe_requests\":[\"p9-a\",\"p9-b\"],\"completion\":{\"token\":\"p9-a\",\"generation\":9,\"evidence\":\"VERIFIED_PASS\",\"currentness\":\"CURRENT\",\"contradiction\":false,\"now\":4,\"deadline\":10},\"fallback\":\"NONE\"}},\n {\"case_id\":\"containment_fallback_is_not_authority\",\"family\":\"fallback_boundary\",\"oracle\":{\"state\":\"OPEN\",\"completion\":\"NO_PROBE_RESULT\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"CONTAINMENT\",\"authority\":false},\"case\":{\"state\":\"OPEN\",\"generation\":11,\"active_probe\":null,\"probe_requests\":[],\"completion\":null,\"fallback\":\"CONTAINMENT\"}},\n {\"case_id\":\"unknown_authority_fallback_rejected\",\"family\":\"fallback_boundary\",\"oracle\":{\"state\":\"OPEN\",\"completion\":\"NO_PROBE_RESULT\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"UNKNOWN\",\"authority\":false},\"case\":{\"state\":\"OPEN\",\"generation\":11,\"active_probe\":null,\"probe_requests\":[],\"completion\":null,\"fallback\":\"ADMIT_ACTION\"}},\n {\"case_id\":\"stale_evidence_cannot_close\",\"family\":\"evidence_currentness\",\"oracle\":{\"state\":\"OPEN\",\"completion\":\"REOPENED_BAD_EVIDENCE\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"UNKNOWN\",\"authority\":false},\"case\":{\"state\":\"HALF_OPEN\",\"generation\":12,\"active_probe\":\"p12\",\"probe_requests\":[],\"completion\":{\"token\":\"p12\",\"generation\":12,\"evidence\":\"VERIFIED_PASS\",\"currentness\":\"STALE\",\"contradiction\":false,\"now\":2,\"deadline\":10},\"fallback\":\"UNKNOWN\"}},\n {\"case_id\":\"expired_probe_cannot_close\",\"family\":\"deadline_race\",\"oracle\":{\"state\":\"OPEN\",\"completion\":\"REOPENED_BAD_EVIDENCE\",\"accepted_probes\":[],\"denied_probes\":[],\"fallback\":\"UNKNOWN\",\"authority\":false},\"case\":{\"state\":\"HALF_OPEN\",\"generation\":13,\"active_probe\":\"p13\",\"probe_requests\":[],\"completion\":{\"token\":\"p13\",\"generation\":13,\"evidence\":\"VERIFIED_PASS\",\"currentness\":\"CURRENT\",\"contradiction\":false,\"now\":11,\"deadline\":10},\"fallback\":\"UNKNOWN\"}}\n]\n"
CORPUS_GIT_BLOB_SHA="db1ed31c93ebb92521a0a5d7c48d5f0012dc9747"
BREAKER_GIT_BLOB_SHA="f58c822487a65b37a7832278c5eb1e39a64ffd39"
def main():
    fixtures=json.loads(CORPUS_TEXT)
    rows=[]
    for fixture in fixtures:
        # Oracle labels never enter the candidate transition function.
        predicted=simulate(fixture["case"])
        expected=fixture["oracle"]
        rows.append({"case_id":fixture["case_id"],"family":fixture["family"],
                     "predicted":predicted,"expected":expected,
                     "match":predicted==expected})
    mismatches=[r["case_id"] for r in rows if not r["match"]]
    total_accepted=sum(len(r["predicted"]["accepted_probes"]) for r in rows)
    total_denied=sum(len(r["predicted"]["denied_probes"]) for r in rows)
    authorities=sum(bool(r["predicted"]["authority"]) for r in rows)
    raw={"schema":"circuit-breaker-5375-boundary-raw-v1",
         "allocation":"circuit-breaker-5375-half-open-boundary-20260930-01",
         "runtime":{"python":platform.python_version(),"platform":sys.platform,"container":False},
         "source_identity":{"breaker_git_blob_sha":BREAKER_GIT_BLOB_SHA,"corpus_git_blob_sha":CORPUS_GIT_BLOB_SHA},
         "rows":rows,
         "counts":{"cases":len(rows),"exact_matches":len(rows)-len(mismatches),"mismatches":len(mismatches),
                   "accepted_probe_permits":total_accepted,"denied_probe_requests":total_denied,"authority_outcomes":authorities},
         "side_effects":{"dispatches":0,"model_calls":0,"gpu_calls":0,"network_calls":0,"authority_grants":0},
         "disposition":"PASS_CIRCUIT_BOUNDARY_SCOPED" if not mismatches and not authorities else "FAIL_CIRCUIT_BOUNDARY"}
    print(json.dumps(raw,sort_keys=True,separators=(",",":")))
    return 0
if __name__=="__main__": raise SystemExit(main())
